@namespace sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)" role="button" aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                <span class="step-badge">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
            @if (stepIndex < StepNames.Count - 1)
            {
                <li class="step-connector @status" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnNavigateToStep { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnNavigateToStep.InvokeAsync(step);
        }
    }
}

@namespace sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Company" @onchange="e => UpdateField(nameof(Company), e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Title" @onchange="e => UpdateField(nameof(Title), e.Value?.ToString())" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateStartDate(e.Value?.ToString())" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent" @onchange="e => UpdateEndDate(e.Value?.ToString())" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => UpdateIsCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" @onchange="e => UpdateField(nameof(Description), e.Value?.ToString())">@Description</textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryUpdate> OnEntryChanged { get; set; }

    private void UpdateField(string field, string? value)
    {
        var update = new WorkEntryUpdate(Index, field, value, StartDate, EndDate, IsCurrent);
        OnEntryChanged.InvokeAsync(update);
    }

    private void UpdateStartDate(string? value)
    {
        var date = string.IsNullOrEmpty(value) ? (DateTime?)null : DateTime.Parse(value);
        var update = new WorkEntryUpdate(Index, nameof(StartDate), null, date, EndDate, IsCurrent);
        OnEntryChanged.InvokeAsync(update);
    }

    private void UpdateEndDate(string? value)
    {
        var date = string.IsNullOrEmpty(value) ? (DateTime?)null : DateTime.Parse(value);
        var update = new WorkEntryUpdate(Index, nameof(EndDate), null, StartDate, date, IsCurrent);
        OnEntryChanged.InvokeAsync(update);
    }

    private void UpdateIsCurrent(bool value)
    {
        var update = new WorkEntryUpdate(Index, nameof(IsCurrent), null, StartDate, value ? null : EndDate, value);
        OnEntryChanged.InvokeAsync(update);
    }

    public record WorkEntryUpdate(int Index, string Field, string? StringValue, DateTime? StartDate, DateTime? EndDate, bool IsCurrent);
}

@namespace sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Components.Pages.Apply

<div class="reference-form">
    <h4>Reference @(Index + 1)</h4>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" class="form-control" value="@Name" @onchange="e => Update(nameof(Name), e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" class="form-control" value="@Relationship" @onchange="e => Update(nameof(Relationship), e.Value?.ToString() ?? "")" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" class="form-control" value="@Email" @onchange="e => Update(nameof(Email), e.Value?.ToString() ?? "")" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" class="form-control" value="@Phone" @onchange="e => Update(nameof(Phone), e.Value?.ToString() ?? "")" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceUpdate> OnReferenceChanged { get; set; }

    private void Update(string field, string value)
    {
        OnReferenceChanged.InvokeAsync(new ReferenceUpdate(Index, field, value));
    }

    public record ReferenceUpdate(int Index, string Field, string Value);
}

