@namespace sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" class="form-control" value="@FullName" @onchange="e => FullName = e.Value?.ToString() ?? """ />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" class="form-control" value="@Email" @onchange="e => Email = e.Value?.ToString() ?? """ />
        @if (IsValidatingEmail)
        {
            <span class="validation-hint">Validating email...</span>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" class="form-control" value="@Phone" @onchange="e => Phone = e.Value?.ToString() ?? """ />
        </div>
        <div class="form-group">
            <label>Address *</label>
            <input type="text" class="form-control" value="@Address" @onchange="e => Address = e.Value?.ToString() ?? """ />
        </div>
    </div>

    <div class="step-actions">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidatingEmail">Next</button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidatingEmail;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidatingEmail = true;
        StateHasChanged();

        var emailValid = await ValidateEmail(Email);
        IsValidatingEmail = false;

        if (!emailValid)
        {
            ErrorMessage = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

@namespace sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        var index = i;
        <WorkEntryForm Index="index"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       ShowRemove="@(Entries.Count > 1)"
                       OnRemove="() => RemoveEntry(index)"
                       OnEntryChanged="HandleEntryChanged" />
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-actions">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new() { new() };
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private void HandleEntryChanged(WorkEntryForm.WorkEntryUpdate update)
    {
        var entry = Entries[update.Index];
        switch (update.Field)
        {
            case nameof(WorkEntryModel.Company):
                entry.Company = update.StringValue ?? "";
                break;
            case nameof(WorkEntryModel.Title):
                entry.Title = update.StringValue ?? "";
                break;
            case nameof(WorkEntryModel.Description):
                entry.Description = update.StringValue ?? "";
                break;
            case nameof(WorkEntryModel.StartDate):
                entry.StartDate = update.StartDate;
                break;
            case nameof(WorkEntryModel.EndDate):
                entry.EndDate = update.EndDate;
                break;
            case nameof(WorkEntryModel.IsCurrent):
                entry.IsCurrent = update.IsCurrent;
                if (update.IsCurrent) entry.EndDate = null;
                break;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                ErrorMessage = "Each position requires a company name, job title, and start date.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var r = References[i];
        <ReferenceForm Index="index"
                       Name="@r.Name"
                       Relationship="@r.Relationship"
                       Email="@r.Email"
                       Phone="@r.Phone"
                       ShowRemove="@(References.Count > 2)"
                       OnRemove="() => RemoveReference(index)"
                       OnReferenceChanged="HandleReferenceChanged" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-actions">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new() { new(), new() };
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void HandleReferenceChanged(ReferenceForm.ReferenceUpdate update)
    {
        var r = References[update.Index];
        switch (update.Field)
        {
            case nameof(ReferenceModel.Name): r.Name = update.Value; break;
            case nameof(ReferenceModel.Relationship): r.Relationship = update.Value; break;
            case nameof(ReferenceModel.Email): r.Email = update.Value; break;
            case nameof(ReferenceModel.Phone): r.Phone = update.Value; break;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference requires a name, relationship, and email.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea class="form-control cover-letter-textarea" rows="12" maxlength="@MaxLength"
                  @oninput="HandleInput" value="@CoverLetter"></textarea>
        <span class="character-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </span>
    </div>

    <div class="step-actions">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;

    private void HandleInput(ChangeEventArgs e)
    {
        CoverLetter = e.Value?.ToString() ?? "";
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Components.Pages.Apply
@using sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Models

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        <div class="step-actions">
            <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntry> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public Func<Task<int>> SubmitApplication { get; set; } = default!;

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        ErrorMessage = null;
        IsSubmitting = true;
        StateHasChanged();

        try
        {
            ApplicationId = await SubmitApplication();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

