@page "/apply"
@namespace sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Components.Pages.Apply
@using sv_4e3feb1da2ab4e7a9a8ef083bdfe7120.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <StepIndicator CurrentStep="currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalInfo.FullName"
                              Email="@personalInfo.Email"
                              Phone="@personalInfo.Phone"
                              Address="@personalInfo.Address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries" OnNext="HandleWorkHistoryNext" OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        WorkEntries="@GetWorkEntries()"
                        References="@GetReferences()"
                        CoverLetter="@coverLetter"
                        OnEditStep="NavigateToStep"
                        OnBack="GoBack"
                        SubmitApplication="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep = 0;

    // Step 1 state
    private (string FullName, string Email, string Phone, string Address) personalInfo = ("", "", "", "");

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        if (step >= 0 && step <= 4)
            currentStep = step;
    }

    private void GoBack() => currentStep--;

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalInfo = (result.FullName, result.Email, result.Phone, result.Address);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }

    private PersonalInfo GetPersonalInfo() =>
        new(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address);

    private List<WorkEntry> GetWorkEntries() =>
        workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.EndDate, e.Description)).ToList();

    private List<Reference> GetReferences() =>
        references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

    private async Task<int> HandleSubmit()
    {
        var application = new JobApplication(GetPersonalInfo(), new WorkHistory(GetWorkEntries()), GetReferences(), coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

